package dev.inkstone.core.calc.num

import kotlin.test.Test
import kotlin.test.assertEquals

/**
 * Dec's four operations against 400 seeded random cases answered by Python 3.14's `decimal`
 * module: the exact result, rounded once to 15 significant digits `ROUND_HALF_UP` (half away
 * from zero), with anything below 10⁻⁹⁹ in magnitude written as 0 and overflow kept
 * (CALCULATOR.md §3). Generated by `arithgen.py` in the session scratchpad and pasted unchanged.
 *
 * Operands mix random digits with runs of 9s, runs of 5s and powers of ten, at exponents from
 * −99 to 99; a third of the additions and subtractions nearly cancel. This table exists because
 * a hand-written one missed a Long overflow in division whenever the dividend's digits were
 * more than about 10⁴ times the divisor's — every hand-picked quotient had a small dividend.
 */
class DecArithmeticReferenceTest {
    private class Case(val a: String, val op: Char, val b: String, val expected: String)

    @Test
    fun `four operations match an independent exact reference`() {
        for (c in cases) {
            val a = d(c.a)
            val b = d(c.b)
            val actual = when (c.op) {
                '+' -> a + b
                '-' -> a - b
                '*' -> a * b
                else -> a / b
            }
            assertEquals(d(c.expected), actual, "${c.a} ${c.op} ${c.b}")
        }
    }

    private val cases = listOf(
